G=load(); print(sorted(G))
# Rule model v2:
#  1: right x2, then copy up (RRU)
#  2: left until col1, copy at end (LLLL-style)
#  3: down x2, copy at end
#  6: up (r-1) steps, copy at top end (verified demos 4,6)
#  crossings (cell on >=2 beams) -> 4; diagonal down-left spark from crossing -> 4 until edge
def solve(T):
    H,W=len(T),len(T[0])
    pts=[(r,c,T[r][c]) for r in range(H) for c in range(W) if T[r][c]]
    beams=[]  # set of cells per marker beam (excluding copy)
    for r,c,v in pts:
        if v==1: moves=[(0,1),(0,1)]
        elif v==2: moves=[]; cc=c
                    while cc>1: moves.append((r,cc-1)); cc-=1
        elif v==3: moves=[(r+1,c)]*2
        else:      # 6: up r-1
                    moves=[(rr,c) for rr in range(1,r)]
        beams.append(set(moves))
    # crossings
    cov={}
    for i,mset in enumerate(beams):
        for p in mset: cov.setdefault(p,set()).add(i)
    four=set()
    for p,s in cov.items():
        if len(s)>=2: four.add(p)
    sparks=set()
    for p in four:
        rr,cc=p
        while True:
            rr+=1; cc-=1
            if not(0<=rr<H and 0<=cc<W): break
            sparks.add((rr,cc))
    out=[row[:] for row in T]
    for i,mset in enumerate(beams):
        for p in mset:
            if p not in four: out[p[0]][p[1]]=5
    for r,c,v in pts: out[r][c]=v
    for p in four: out[p[0]][p[1]]=4
    for s in sparks: out[s[0]][s[1]]=4
    # copies
    for r,c,v in pts:
        if v==1: cp=(r-1,c+2)
        elif v==2: cp=(r,1)
        elif v==3: cp=(r+2,c)
        else: cp=(1,c)
        out[cp[0]][cp[1]]=v
    return out
